-- # Defaults and nullability.
CREATE TABLE t (a INT DEFAULT -3 NOT NULL, b VARCHAR(10) DEFAULT 'x', c TIMESTAMP(0) DEFAULT LOCALTIMESTAMP(0), d INT DEFAULT NULL, e VARCHAR(10) DEFAULT CURRENT_SCHEMA, f INT, g INT, PRIMARY KEY (f, g));
SELECT column_name, column_default, is_nullable FROM information_schema.columns WHERE table_name = 'T';
-- msg: CREATE TABLE 1
-- COLUMN_NAME: A COLUMN_DEFAULT: -3 IS_NULLABLE: NO
-- COLUMN_NAME: B COLUMN_DEFAULT: 'x' IS_NULLABLE: YES
-- COLUMN_NAME: C COLUMN_DEFAULT: LOCALTIMESTAMP(0) IS_NULLABLE: YES
-- COLUMN_NAME: D COLUMN_DEFAULT: NULL IS_NULLABLE: YES
-- COLUMN_NAME: E COLUMN_DEFAULT: CURRENT_SCHEMA IS_NULLABLE: YES
-- COLUMN_NAME: F COLUMN_DEFAULT: NULL IS_NULLABLE: NO
-- COLUMN_NAME: G COLUMN_DEFAULT: NULL IS_NULLABLE: NO

-- # A column without a default has a null COLUMN_DEFAULT, which isn't the same
-- # as DEFAULT NULL.
CREATE TABLE t (a INT DEFAULT NULL, b INT);
SELECT column_name, column_default IS NULL FROM information_schema.columns WHERE table_name = 'T';
-- msg: CREATE TABLE 1
-- COLUMN_NAME: A COL2: FALSE
-- COLUMN_NAME: B COL2: TRUE

